/**
 * Laser Tumbler Simple Page Styles
 * Clean, modern design for product information display
 */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue so the page
   keeps its exact look. Map them to shared_components/css/tokens.css names when the page is redesigned;
   every rule below uses var(). Raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --laser-tumbler-simple-gray: #666;
    --laser-tumbler-simple-gray-dark: #333;
    --laser-tumbler-simple-cyan: #06c;
    --laser-tumbler-simple-yellow-3: #f0d9a8;
    --laser-tumbler-simple-green: #c4d4ca;
    --laser-tumbler-simple-orange: #ffa726;
    --laser-tumbler-simple-cyan-2: #004085;
    --laser-tumbler-simple-cyan-3: #2196f3;
    --laser-tumbler-simple-cyan-4: #1976d2;
    --laser-tumbler-simple-green-2: #9db8a8;
    --laser-tumbler-simple-gray-2: #888;
    --laser-tumbler-simple-red-tint: #f2c4c0;
}
/* stylelint-enable color-no-hex */

/* ===== Page Layout ===== */
body {
    background: var(--gray-100);
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px;
}

/* ===== Hero Section ===== */
.hero-section {
    background: white;
    border-radius: 8px;
    padding: 40px;
    margin-bottom: 30px;
    box-shadow: 0 2px 8px rgb(0 0 0 / 10%);
}

.hero-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 40px;
    align-items: center;
}

.hero-image {
    text-align: center;
}

.product-image-main {
    max-width: 100%;
    height: auto;
    border-radius: 8px;
}

.hero-info h1 {
    font-size: 32px;
    margin: 0 0 10px;
    color: var(--print-green);
}

.product-subtitle {
    font-size: 18px;
    color: var(--laser-tumbler-simple-gray);
    margin: 0 0 20px;
}

.product-sku {
    font-size: 14px;
    color: var(--laser-tumbler-simple-gray);
    margin: 8px 0 16px;
    font-weight: 500;
}

.product-sku span {
    color: var(--print-green);
    font-weight: 600;
}

.product-description {
    font-size: 16px;
    line-height: 1.6;
    color: var(--print-ink-soft);
    margin-bottom: 20px;
}

/* ===== Color Selector ===== */
.color-selector {
    margin: 30px 0;
    padding: 0;
    border: none;
}

.color-selector legend {
    font-size: 18px;
    font-weight: 600;
    color: var(--laser-tumbler-simple-gray-dark);
    margin-bottom: 15px;
    padding: 0;
}

.selected-color-name {
    color: var(--print-green);
    font-weight: 700;
}

.color-grid {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 12px;
    max-width: 550px;
}

.color-swatch-container {
    position: relative;
}

.color-swatch-input {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
}

.color-swatch {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
    padding: 4px;
    border-radius: 8px;
}

.color-preview {
    width: 70px;
    height: 70px;
    border-radius: 50%;
    border: 2px solid var(--gray-200);
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    transition: all 0.2s ease;
    background-size: cover;
    background-position: center;
}

.color-name {
    font-size: 12px;
    color: var(--laser-tumbler-simple-gray);
    text-align: center;
    line-height: 1.2;
    max-width: 70px;
    overflow: hidden;
    text-overflow: ellipsis;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
}

/* Hover State */
.color-swatch:hover .color-preview {
    border-color: var(--laser-tumbler-simple-gray-dark);
    transform: scale(1.05);
    box-shadow: 0 2px 8px rgb(0 0 0 / 15%);
}

/* Selected State */
.color-swatch-input:checked + .color-swatch .color-preview {
    border: 3px solid var(--print-green);
    box-shadow: 0 0 0 2px white, 0 0 0 5px var(--print-green);
}

.color-swatch-input:checked + .color-swatch .color-preview::after {
    content: '\2713';
    position: absolute;
    color: white;
    font-size: 24px;
    font-weight: bold;
    text-shadow: 0 0 3px rgb(0 0 0 / 50%);
}

.color-swatch-input:checked + .color-swatch .color-name {
    color: var(--print-green);
    font-weight: 600;
}

/* Focus State (keyboard navigation) */
.color-swatch-input:focus-visible + .color-swatch .color-preview {
    outline: 3px solid var(--print-green);
    outline-offset: 2px;
}

/* Loading State */
.color-loading {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 20px;
    color: var(--laser-tumbler-simple-gray);
    font-size: 14px;
}

.color-loading-spinner {
    width: 20px;
    height: 20px;
    border: 3px solid var(--gray-100);
    border-top: 3px solid var(--print-green);
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

/* Screen Reader Only */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* ===== Inventory Badge ===== */
.inventory-status {
    margin-top: 20px;
}

.inventory-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 20px;
    border-radius: 20px;
    font-weight: 600;
    font-size: 14px;
    margin-bottom: 15px;
}

.inventory-badge.in-stock {
    background: var(--store-green-100);
    color: var(--print-green-dark);
}

.inventory-badge.low-stock {
    background: var(--amber-100);
    color: var(--bs-warning-ink);
}

.inventory-badge.out-of-stock {
    background: var(--red-100);
    color: var(--color-ae-dark);
}

.inventory-details {
    display: flex;
    gap: 20px;
    font-size: 14px;
}

.inventory-item {
    display: flex;
    gap: 8px;
}

.inventory-label {
    color: var(--laser-tumbler-simple-gray);
}

.inventory-value {
    font-weight: 600;
    color: var(--laser-tumbler-simple-gray-dark);
}

/* Dual Inventory Grid Layout */
.inventory-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin-top: 20px;
}

.inventory-section {
    background: var(--gray-50);
    border: 2px solid var(--gray-200);
    border-radius: 8px;
    padding: 20px;
    transition: all 0.3s ease;
}

.inventory-section:hover {
    border-color: var(--gray-200);
    box-shadow: 0 2px 8px rgb(0 0 0 / 10%);
}

.inventory-section-title {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 16px;
    font-weight: 600;
    color: var(--laser-tumbler-simple-gray-dark);
    margin-bottom: 15px;
}

.inventory-section-title i {
    font-size: 18px;
}

/* Local Warehouse Inventory - Emphasized with brand green */
.local-inventory {
    background: linear-gradient(135deg, var(--brand-50) 0%, var(--color-surface) 100%);
    border-color: var(--print-green);
    border-width: 3px;
}

.local-inventory .inventory-section-title {
    color: var(--print-green);
}

.local-inventory .inventory-section-title i {
    color: var(--print-green);
}

/* Supplier Inventory - Standard styling */
.supplier-inventory {
    background: var(--color-surface);
}

.supplier-inventory .inventory-section-title {
    color: var(--gray-600);
}

.supplier-inventory .inventory-section-title i {
    color: var(--gray-500);
}

/* Responsive: Stack on mobile */
@media (width <= 768px) {
    .inventory-grid {
        grid-template-columns: 1fr;
        gap: 15px;
    }
}

/* ===== Pricing Section ===== */
.pricing-section {
    background: white;
    border-radius: 8px;
    padding: 40px;
    margin-bottom: 30px;
    box-shadow: 0 2px 8px rgb(0 0 0 / 10%);
}

.pricing-section h2 {
    font-size: 28px;
    margin: 0 0 10px;
    color: var(--print-green);
}

.pricing-subtitle {
    font-size: 16px;
    color: var(--laser-tumbler-simple-gray);
    margin: 0 0 30px;
}

/* ===== Pricing Table ===== */
.pricing-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 16px;
}

.pricing-table thead {
    background: var(--print-green);
    color: white;
}

.pricing-table th {
    padding: 15px;
    text-align: left;
    font-weight: 600;
}

.pricing-table tbody tr {
    border-bottom: 1px solid var(--gray-200);
    transition: background 0.2s;
}

.pricing-table tbody tr:hover {
    background: var(--gray-50);
}

.pricing-table tbody tr.highlight-tier {
    background: var(--store-rush-soft);
    border-left: 4px solid var(--laser-tumbler-simple-orange);
}

.pricing-table tbody tr.highlight-tier:hover {
    background: var(--amber-100);
}

.pricing-table td {
    padding: 20px 15px;
}

.tier-range {
    font-weight: 600;
}

.tier-qty {
    font-size: 18px;
    color: var(--laser-tumbler-simple-gray-dark);
    margin-bottom: 5px;
}

.tier-desc {
    font-size: 14px;
    color: var(--laser-tumbler-simple-gray);
}

.tier-price {
    text-align: center;
}

.price-large {
    font-size: 28px;
    font-weight: 700;
    color: var(--print-green);
}

.price-small {
    font-size: 14px;
    color: var(--laser-tumbler-simple-gray);
}

.tier-total {
    text-align: right;
}

.total-price {
    font-size: 22px;
    font-weight: 600;
    color: var(--laser-tumbler-simple-gray-dark);
}

.total-qty {
    font-size: 14px;
    color: var(--laser-tumbler-simple-gray);
}

/* ===== Unavailable Pricing Tier ===== */
.pricing-tier-unavailable {
    opacity: 0.5;
    color: var(--print-line);
}

.pricing-tier-unavailable .tier-qty,
.pricing-tier-unavailable .price-large,
.pricing-tier-unavailable .total-price {
    text-decoration: line-through;
    color: var(--print-line);
}

.pricing-tier-unavailable .tier-desc,
.pricing-tier-unavailable .price-small,
.pricing-tier-unavailable .total-qty {
    color: var(--gray-400);
}

/* ===== Pricing Warning Row ===== */
.pricing-warning-row {
    background: var(--amber-100);
    border-left: 4px solid var(--bs-warning);
}

.pricing-warning-row:hover {
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    background: var(--amber-100) !important;
}

.pricing-warning {
    color: var(--bs-warning-ink);
    font-weight: 500;
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    padding: 12px 15px !important;
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    border-bottom: none !important;
}

.pricing-warning i {
    margin-right: 8px;
    color: var(--bs-warning);
    font-size: 16px;
}

.pricing-warning span {
    font-size: 14px;
    line-height: 1.5;
}

/* ===== Pricing Info Row (Handling Fee Explanation) ===== */
.pricing-info-row {
    background: var(--color-floor-tint);
    border-left: 4px solid var(--laser-tumbler-simple-cyan);
}

.pricing-info-row:hover {
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    background: var(--color-floor-tint) !important;
}

.pricing-info {
    color: var(--laser-tumbler-simple-cyan-2);
    font-weight: 500;
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    padding: 12px 15px !important;
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    border-bottom: none !important;
}

.pricing-info i {
    margin-right: 8px;
    color: var(--laser-tumbler-simple-cyan);
    font-size: 16px;
}

.pricing-info span {
    font-size: 14px;
    line-height: 1.5;
}

/* ===== Pricing Notes ===== */
.pricing-notes {
    margin-top: 25px;
    padding: 20px;
    background: var(--color-floor-tint);
    border-left: 4px solid var(--laser-tumbler-simple-cyan-3);
