    left: 0;
    width: 100%;
    height: 100%;
    background: rgb(0 0 0 / 90%);
    z-index: 10000;
}

.lightbox-content {
    position: relative;
    max-width: 90%;
    max-height: 90%;
}

.lightbox-content img {
    max-width: 100%;
    max-height: 90vh;
    border-radius: 8px;
}

.lightbox-close {
    position: absolute;
    top: -40px;
    right: 0;
    font-size: 40px;
    color: white;
    cursor: pointer;
    font-weight: 300;
}

.lightbox-close:hover {
    color: var(--gray-300);
}

/* ===== CTA Section ===== */
.cta-section {
    background: linear-gradient(135deg, var(--print-green) 0%, var(--store-green-900) 100%);
    color: white;
    border-radius: 8px;
    padding: 40px;
    text-align: center;
    margin-bottom: 30px;
    box-shadow: 0 2px 8px rgb(0 0 0 / 10%);
}

.cta-section h2 {
    font-size: 32px;
    margin: 0 0 15px;
}

.cta-section p {
    font-size: 18px;
    margin: 0 0 25px;
    opacity: 0.9;
}

.cta-button {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: white;
    color: var(--print-green);
    padding: 15px 30px;
    border-radius: 30px;
    font-size: 18px;
    font-weight: 600;
    text-decoration: none;
    transition: transform 0.2s, box-shadow 0.2s;
}

.cta-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgb(255 255 255 / 30%);
}

/* ===== Loading State ===== */
#loading-spinner {
    display: flex; /* hidden attribute (guarded below) hides it at rest */
    justify-content: center;
    align-items: center;
    padding: 60px;
}

.spinner {
    width: 50px;
    height: 50px;
    border: 4px solid var(--gray-100);
    border-top: 4px solid var(--print-green);
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

#page-content.loading {
    opacity: 0.5;
    pointer-events: none;
}

/* ===== Error State ===== */
#error-message {
    background: var(--red-100);
    color: var(--color-ae-dark);
    padding: 20px;
    border-radius: 8px;
    margin: 20px 0;
    text-align: center;
    font-size: 16px;
}

/* ===== Responsive Design ===== */
@media (width <= 768px) {
    /* Color Selector Responsive */
    .color-grid {
        grid-template-columns: repeat(4, 1fr);
        gap: 10px;
    }

    .color-preview {
        width: 50px;
        height: 50px;
        min-width: 48px;  /* WCAG touch target minimum */
        min-height: 48px; /* WCAG touch target minimum */
    }

    .color-name {
        font-size: 11px;
        max-width: 50px;
    }

    .color-swatch-input:checked + .color-swatch .color-preview::after {
        font-size: 18px;
    }

    /* Existing responsive styles */
    .hero-content {
        grid-template-columns: 1fr;
        gap: 30px;
    }

    .hero-section {
        padding: 30px 20px;
    }

    .pricing-section {
        padding: 30px 20px;
    }

    .pricing-table {
        font-size: 14px;
    }

    .pricing-table th,
    .pricing-table td {
        padding: 12px 8px;
    }

    .price-large {
        font-size: 22px;
    }

    .total-price {
        font-size: 18px;
    }

    .tier-qty {
        font-size: 16px;
    }

    /* Pricing warning responsive */
    .pricing-warning {
        font-size: 13px;
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        padding: 10px 12px !important;
    }

    .pricing-warning i {
        display: block;
        margin-bottom: 4px;
        margin-right: 0;
    }

    .inventory-details {
        flex-direction: column;
        gap: 10px;
    }

    .product-gallery {
        grid-template-columns: repeat(2, 1fr);
    }

    .cta-section h2 {
        font-size: 24px;
    }

    .cta-section p {
        font-size: 16px;
    }
}

@media (width <= 480px) {
    .hero-info h1 {
        font-size: 24px;
    }

    .product-subtitle {
        font-size: 16px;
    }

    .pricing-section h2 {
        font-size: 22px;
    }

    .tier-total {
        display: none; /* Hide totals on very small screens */
    }
}

/* ============================================================
   Logo Mockup + Instant Quote section (laser-tumbler-mockup.js)
   ============================================================ */

.mockup-section {
    padding: 60px 0;
    background: var(--gray-50);
    border-top: 3px solid var(--print-green);
}

.mockup-section h2 {
    color: var(--print-green);
    font-size: 32px;
    margin-bottom: 8px;
    text-align: center;
}

.mockup-subtitle {
    text-align: center;
    color: var(--print-ink-soft);
    margin-bottom: 36px;
}

.mockup-layout {
    display: grid;
    grid-template-columns: minmax(300px, 420px) 1fr;
    gap: 36px;
    align-items: start;
}

.mockup-step {
    background: var(--color-surface);
    border: 1px solid var(--gray-200);
    border-radius: 10px;
    padding: 20px;
    margin-bottom: 18px;
}

.mockup-step h3 {
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--print-green);
    font-size: 18px;
    margin: 0 0 14px;
}

.mockup-step-num {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    border-radius: 50%;
    background: var(--print-green);
    color: var(--color-on-brand);
    font-size: 14px;
    font-weight: 700;
    flex-shrink: 0;
}

/* Upload drop zone */
.ltmk-drop-zone {
    border: 2px dashed var(--laser-tumbler-simple-green-2);
    border-radius: 10px;
    padding: 28px 16px;
    text-align: center;
    color: var(--print-ink-soft);
    cursor: pointer;
    transition: border-color 0.15s, background 0.15s;
}

.ltmk-drop-zone i {
    font-size: 28px;
    color: var(--print-green);
    margin-bottom: 8px;
}

.ltmk-drop-zone:hover,
.ltmk-drop-zone:focus-visible,
.ltmk-drop-zone--active {
    border-color: var(--print-green);
    background: var(--store-green-50);
    outline: none;
}

.ltmk-logo-info {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 12px;
    padding: 8px 10px;
    background: var(--store-green-50);
    border-radius: 8px;
}

.ltmk-logo-thumb {
    width: 36px;
    height: 36px;
    border-radius: 6px;
    background-color: var(--color-on-brand);
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    border: 1px solid var(--gray-300);
    flex-shrink: 0;
}

.ltmk-logo-name {
    flex: 1;
    font-size: 14px;
    color: var(--laser-tumbler-simple-gray-dark);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ltmk-logo-remove {
    border: none;
    background: none;
    color: var(--red-700);
    font-size: 20px;
    cursor: pointer;
    line-height: 1;
    padding: 2px 6px;
}

/* Artwork warning */
.ltmk-warning {
    margin-top: 12px;
    padding: 14px;
    background: var(--red-50);
    border: 1px solid var(--laser-tumbler-simple-yellow-3);
    border-radius: 8px;
}

.ltmk-warning h4 {
    margin: 0 0 8px;
    color: var(--print-gold);
    font-size: 15px;
}

.ltmk-warning p {
    margin: 0 0 12px;
    font-size: 14px;
    color: var(--print-ink-soft);
}

.ltmk-warning-actions {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}

/* Buttons */
.ltmk-btn {
    border: 1px solid var(--print-green);
    background: var(--color-surface);
    color: var(--print-green);
    border-radius: 8px;
    padding: 9px 16px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
}

.ltmk-btn:hover {
    background: var(--store-green-50);
}

.ltmk-btn--primary {
    background: var(--print-green);
    color: var(--color-on-brand);
    width: 100%;
    padding: 13px 16px;
    font-size: 16px;
}

.ltmk-btn--primary:hover {
    background: var(--print-green-dark);
}

.ltmk-btn--secondary {
    background: var(--color-surface);
}

/* Size controls */
.ltmk-slider-label {
    display: block;
    font-size: 14px;
    color: var(--laser-tumbler-simple-gray-dark);
    margin-bottom: 6px;
}

#ltmk-size-slider {
    width: 100%;
    accent-color: var(--print-green);
}

.ltmk-size-actions {
    display: flex;
    gap: 10px;
    margin-top: 10px;
}

.ltmk-hint {
    margin: 10px 0 0;
    font-size: 13px;
    color: var(--gray-500);
}

/* Quote */
.ltmk-qty-label {
    display: block;
    font-size: 14px;
    color: var(--laser-tumbler-simple-gray-dark);
    margin-bottom: 6px;
}

#ltmk-qty {
    width: 120px;
    padding: 9px 12px;
    border: 1px solid var(--laser-tumbler-simple-green);
    border-radius: 8px;
    font-size: 16px;
}

.ltmk-quote-result {
    margin-top: 14px;
}

.ltmk-quote-line {
    display: flex;
    justify-content: space-between;
    font-size: 14px;
    color: var(--gray-700);
    padding: 5px 0;
}

.ltmk-quote-total {
    display: flex;
    justify-content: space-between;
    font-size: 18px;
    font-weight: 700;
    color: var(--print-green);
    border-top: 2px solid var(--print-green);
    margin-top: 8px;
    padding-top: 10px;
}

.ltmk-quote-note {
    margin: 10px 0 0;
    font-size: 12px;
    color: var(--laser-tumbler-simple-gray-2);
}

.ltmk-quote-warning {
    display: flex;
    gap: 8px;
    align-items: flex-start;
    font-size: 14px;
    color: var(--print-gold);
    background: var(--red-50);
    border: 1px solid var(--laser-tumbler-simple-yellow-3);
    border-radius: 8px;
    padding: 12px;
}

/* Preview pane */
.mockup-preview {
    position: relative;
    background: var(--color-surface);
    border: 1px solid var(--gray-200);
    border-radius: 10px;
    padding: 20px;
    text-align: center;
}

#ltmk-canvas {
    max-width: 100%;
    height: auto;
    cursor: grab;
    touch-action: none;
    border-radius: 8px;
}

#ltmk-canvas:active {
    cursor: grabbing;
}

#ltmk-canvas:focus-visible {
    outline: 3px solid var(--print-green);
    outline-offset: 2px;
}

.ltmk-preview-empty {
    padding: 90px 20px;
    color: var(--print-line);
}

.ltmk-preview-empty i {
    font-size: 42px;
    margin-bottom: 12px;
    display: block;
    color: var(--laser-tumbler-simple-green);
}

.ltmk-preview-loading {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgb(255 255 255 / 70%);
    border-radius: 10px;
}

.ltmk-preview-error {
    margin-top: 12px;
    padding: 12px;
    background: var(--red-50);
    border: 1px solid var(--laser-tumbler-simple-red-tint);
    border-radius: 8px;
    color: var(--red-700);
    font-size: 14px;
}

.ltmk-caption {
    margin: 12px 0 0;
    font-size: 13px;
    color: var(--gray-500);
    font-style: italic;
}

@media (width <= 900px) {
    .mockup-layout {
        grid-template-columns: 1fr;
    }

    .mockup-section h2 {
        font-size: 24px;
    }
}

/* 2026-09-05 review */
.pricing-table th.th-center { text-align: center; }

/* 2026-09-06 review: the hidden attribute must beat any display rule */
/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
[hidden] { display: none !important; }

